<?php
if(!isset($mapaDedicatedQaApp,$consoleBearer,$consoleReviewer,$company))throw new RuntimeException('Isolated source connection QA required.');
// Keep this nested fixture independent from enrollment's before/after counts.
DB::beginTransaction();
$connectionDir=storage_path('app/mapa-source-sync');@mkdir($connectionDir,0700,true);
$connectionPrior=[config('mapa_mobile.source_sync_enabled'),config('mapa_mobile.source_connections_enabled'),config('mapa_mobile.source_connections_demo_enabled')];
config(['mapa_mobile.source_sync_enabled'=>true,'mapa_mobile.source_connections_enabled'=>true,'mapa_mobile.source_connections_demo_enabled'=>true]);
$connectionState=['received_at'=>time(),'changes'=>[],'snapshot'=>['contract'=>'mapa-asr-source-v1','source'=>'https://asrhealth.in','company_id'=>$company,'complete'=>true,'generated_at'=>microtime(true),'source_date'=>'2026-10-06','datasets'=>array_fill_keys(array_keys(\MapaSource\SourceSync::FIELDS),[])]];
$sourceA=['id'=>'DEMO-A','vehicle_number'=>'DEMO-AMB-A','type_id'=>'1','phc_id'=>'DEMO-PHC','institute_type_id'=>'1','vehicle_model'=>null,'model_year'=>null,'parking_type'=>null,'parking_place_name'=>null];
$sourceB=$sourceA;$sourceB['id']='DEMO-B';$sourceB['vehicle_number']='DEMO-AMB-B';
$connectionState['snapshot']['datasets']['ambulances']=[$sourceA,$sourceB];
$sourceDriver=['id'=>'DEMO-D','name'=>'DEMO connection driver','age'=>null,'gender'=>null,'dob'=>null,'doj'=>'2026-10-01','phc_id'=>'DEMO-PHC','mobile_number'=>'9000000000','vehicle_type'=>'Special'];
$sourceHospital=['phc_id'=>'DEMO-PHC','name'=>'DEMO source PHC','type'=>'1'];
$connectionState['snapshot']['datasets']['drivers']=[$sourceDriver];
$connectionState['snapshot']['datasets']['hospitals']=[$sourceHospital];
$connectionPolicy=['enabled'=>true,'company_id'=>$company,'actors'=>[$consoleReviewer->uuid=>['read','review']]];
$writeConnectionState=function()use($connectionDir,&$connectionState){\MapaSource\SourceSync::validate($connectionState['snapshot'],(int)$connectionState['snapshot']['generated_at']);file_put_contents($connectionDir.'/state.json',json_encode($connectionState));};$writeConnectionState();
file_put_contents($connectionDir.'/connections.json',json_encode($connectionPolicy));
$nativeA=row('vehicles',['company_uuid'=>$company,'name'=>'DEMO connection vehicle A','plate_number'=>'DEMO-CON-A','status'=>'active','online'=>false]);
$nativeB=row('vehicles',['company_uuid'=>$company,'name'=>'DEMO connection vehicle B','plate_number'=>'DEMO-CON-B','status'=>'active','online'=>false]);
$foreignNative=row('vehicles',['company_uuid'=>$foreign,'name'=>'DEMO foreign connection vehicle','status'=>'active','online'=>false]);
$connectionDriverUser=row('users',['company_uuid'=>$company,'name'=>'DEMO connection user','email'=>'demo-source-connection@example.invalid','status'=>'active']);
$connectionDriver=row('drivers',['company_uuid'=>$company,'user_uuid'=>$connectionDriverUser,'location'=>$point,'online'=>false]);
$connectionInactiveUser=row('users',['company_uuid'=>$company,'name'=>'DEMO inactive connection user','email'=>'demo-source-inactive@example.invalid','status'=>'inactive']);
$connectionInactiveDriver=row('drivers',['company_uuid'=>$company,'user_uuid'=>$connectionInactiveUser,'location'=>$point,'online'=>false]);
$connectionHospital=row('places',['company_uuid'=>$company,'name'=>'DEMO connection hospital','type'=>'hospital','location'=>$point]);
$connectionBase=row('places',['company_uuid'=>$company,'name'=>'DEMO connection base','type'=>'base','location'=>$point]);
$connectionPickup=row('places',['company_uuid'=>$company,'name'=>'DEMO pickup only','type'=>'pickup','location'=>$point]);
$connectionForeignHospital=row('places',['company_uuid'=>$foreign,'name'=>'DEMO foreign hospital','type'=>'hospital','location'=>$point]);
$connections=new App\MapaMobile\SourceConnectionController;
$connectionReq=function($body=[],$query=[],$token=null)use($consoleBearer){$r=Illuminate\Http\Request::create('/api/int/v1/mapa/source-connections',$body?'POST':'GET',[],[],[],[], $body?json_encode($body):'');$r->query->replace($query);$r->headers->set('Authorization','Bearer '.($token??$consoleBearer));$r->headers->set('Content-Type','application/json');return $r;};
$connectionBody=['dataset'=>'ambulances','source_id'=>'DEMO-A','native_uuid'=>$nativeA,'source_revision'=>App\MapaMobile\SourceConnections::fingerprint($sourceA),'expected_link_revision'=>0,'confirmed'=>true,'reason'=>'DEMO reviewed registration match'];
$resourceCounts=fn()=>array_map(fn($t)=>DB::table($t)->count(),['users','drivers','vehicles','places','orders','positions','mapa_mobile_bindings']);$beforeConnections=$resourceCounts();
check($connections->index($connectionReq([],['dataset'=>'ambulances']))->getData(true)['rows'][0]['connection']==='not_linked','source connection starts explicitly unlinked');
check(count($connections->index($connectionReq([],['dataset'=>'ambulances','options'=>'1']))->getData(true)['rows'])>=2,'native options retain separate reviewed identities');
check($connections->index($connectionReq([],['dataset'=>'ambulances','page'=>'0']))->getStatusCode()===422,'connection options pagination rejects invalid page');
check($connections->store($connectionReq($connectionBody,[],str_repeat('x',40)))->getStatusCode()===401,'invalid native token cannot link source');
$connectionPolicy['actors'][$consoleReviewer->uuid]=['read'];file_put_contents($connectionDir.'/connections.json',json_encode($connectionPolicy));
check($connections->store($connectionReq($connectionBody))->getStatusCode()===403,'crew-review context alone cannot link without explicit integration review grant');
$connectionPolicy['actors'][$consoleReviewer->uuid]=['read','review'];file_put_contents($connectionDir.'/connections.json',json_encode($connectionPolicy));
check($connections->store($connectionReq([...$connectionBody,'native_uuid'=>$foreignNative]))->getStatusCode()===422,'foreign native identity cannot link');
check($connections->store($connectionReq([...$connectionBody,'confirmed'=>false]))->getStatusCode()===422,'mapping requires explicit identity confirmation');
check($connections->store($connectionReq([...$connectionBody,'source_revision'=>str_repeat('a',64)]))->getStatusCode()===409,'changed source identity rejects link');
$linked=$connections->store($connectionReq($connectionBody));check($linked->getStatusCode()===200&&$linked->getData(true)['revision']===1,'reviewed source-to-native identity link commits');
check(DB::table('mapa_source_connection_audit')->where('source_id','DEMO-A')->count()===1,'link writes durable review audit');
check($connections->store($connectionReq($connectionBody))->getStatusCode()===409,'stale link revision cannot silently replay or relink');
check($connections->store($connectionReq([...$connectionBody,'source_id'=>'DEMO-B','source_revision'=>App\MapaMobile\SourceConnections::fingerprint($sourceB)]))->getStatusCode()===409,'duplicate native mapping refused');
$projection=$connections->projection($connectionReq(),'ambulances',$nativeA)->getData(true);
check($projection['connection']==='linked'&&$projection['source']['id']==='DEMO-A'&&$projection['sections']['daily_status']===[],'shared native projection uses exact reviewed source identity');
check($projection['operational_owner']==='MAPA'&&$projection['owner']==='asrhealth.in','source administrative ownership separated from current native operation');
$driverOptions=$connections->index($connectionReq([],['dataset'=>'drivers','options'=>'1']))->getData(true);
$driverOptionIds=array_column($driverOptions['rows']??[],'uuid');
check(in_array($connectionDriver,$driverOptionIds,true)&&!in_array($connectionInactiveDriver,$driverOptionIds,true),'driver connection options require active native user identity');
$driverConnectionBody=['dataset'=>'drivers','source_id'=>'DEMO-D','native_uuid'=>$connectionDriver,'source_revision'=>App\MapaMobile\SourceConnections::fingerprint($sourceDriver),'expected_link_revision'=>0,'confirmed'=>true,'reason'=>'DEMO reviewed driver identity'];
check($connections->store($connectionReq([...$driverConnectionBody,'native_uuid'=>$connectionInactiveDriver]))->getStatusCode()===422,'inactive native driver cannot receive source link');
check($connections->store($connectionReq($driverConnectionBody))->getStatusCode()===200,'reviewed driver identity connection commits');
$driverProjection=$connections->projection($connectionReq(),'drivers',$connectionDriver)->getData(true);
check(($driverProjection['source']['id']??null)==='DEMO-D'&&($driverProjection['sections']['attendance'][0]['id']??null)==='DEMO-D','driver native projection includes exact source identity and PHC attendance');
check(Illuminate\Support\Facades\Schema::hasColumn('places','type'),'native places schema carries hospital/base classification');
$hospitalOptions=$connections->index($connectionReq([],['dataset'=>'hospitals','options'=>'1']));$hospitalOptionIds=array_column($hospitalOptions->getData(true)['rows']??[],'uuid');
check($hospitalOptions->getStatusCode()===200&&in_array($connectionHospital,$hospitalOptionIds,true)&&in_array($connectionBase,$hospitalOptionIds,true)&&!in_array($connectionPickup,$hospitalOptionIds,true)&&!in_array($connectionForeignHospital,$hospitalOptionIds,true),'hospital options include same-company hospital/base and exclude pickups and foreign places');
$hospitalConnectionBody=['dataset'=>'hospitals','source_id'=>'DEMO-PHC','native_uuid'=>$connectionHospital,'source_revision'=>App\MapaMobile\SourceConnections::fingerprint($sourceHospital),'expected_link_revision'=>0,'confirmed'=>true,'reason'=>'DEMO reviewed PHC identity'];
check($connections->store($connectionReq([...$hospitalConnectionBody,'native_uuid'=>$connectionPickup]))->getStatusCode()===422,'pickup-only place cannot receive administrative PHC link');
check($connections->store($connectionReq([...$hospitalConnectionBody,'native_uuid'=>$connectionForeignHospital]))->getStatusCode()===422,'foreign hospital cannot receive PHC link');
check($connections->store($connectionReq($hospitalConnectionBody))->getStatusCode()===200,'reviewed hospital identity connection commits');
$hospitalProjection=$connections->projection($connectionReq(),'hospitals',$connectionHospital)->getData(true);
check(($hospitalProjection['source']['phc_id']??null)==='DEMO-PHC'&&count($hospitalProjection['sections']['ambulances']??[])===2&&count($hospitalProjection['sections']['drivers']??[])===1,'native hospital projection shows exact source PHC fleet and drivers');
check($connections->projection($connectionReq(),'ambulances',$foreignNative)->getStatusCode()===404,'foreign resource projection denied');
$connectionState['snapshot']['datasets']['ambulances'][0]['vehicle_model']='DEMO updated model';$writeConnectionState();
check($connections->projection($connectionReq(),'ambulances',$nativeA)->getData(true)['changed_since_review'],'source update visible without overwriting native fields');
$connectionState['received_at']=time()-121;$writeConnectionState();
check($connections->projection($connectionReq(),'ambulances',$nativeA)->getData(true)['stale'],'stale native source projection explicitly labelled');
check($connections->store($connectionReq([...$connectionBody,'native_uuid'=>$nativeB,'source_revision'=>App\MapaMobile\SourceConnections::fingerprint($connectionState['snapshot']['datasets']['ambulances'][0]),'expected_link_revision'=>1]))->getStatusCode()===409,'stale source cannot relink');
$connectionState['received_at']=time();$connectionState['snapshot']['datasets']['ambulances']=[$sourceB];$writeConnectionState();
check($connections->projection($connectionReq(),'ambulances',$nativeA)->getData(true)['connection']==='removed_at_source','removed source remains review tombstone; no native deletion');
check($connections->store($connectionReq(['action'=>'unlink','dataset'=>'ambulances','source_id'=>'DEMO-A','expected_link_revision'=>1,'confirmed'=>true,'reason'=>'DEMO reviewed source removal']))->getData(true)['revision']===2,'reviewed unlink retained as next audit revision');
check($connections->projection($connectionReq(),'ambulances',$nativeA)->getData(true)['connection']==='not_linked','unlinked native resource no longer exposes old source facts');
$connectionState['snapshot']['datasets']['ambulances']=[$sourceA,$sourceB];$writeConnectionState();
check($connections->store($connectionReq([...$connectionBody,'native_uuid'=>$nativeB,'expected_link_revision'=>2]))->getData(true)['revision']===3,'explicit relink preserves prior history');
check(DB::table('mapa_source_connection_audit')->where('source_id','DEMO-A')->count()===3,'unlink/relink never erases audit history');
config(['mapa_mobile.source_connections_demo_enabled'=>false]);
check($connections->projection($connectionReq(),'ambulances',$nativeB)->getStatusCode()===404,'real mode hides training-linked native identities');
config(['mapa_mobile.source_connections_enabled'=>false]);
check($connections->index($connectionReq([],['dataset'=>'ambulances']))->getStatusCode()===503,'disabled mappings fail closed');
config(['mapa_mobile.source_connections_enabled'=>true,'mapa_mobile.source_connections_demo_enabled'=>true]);
$v2=$connectionState['snapshot'];$v2['contract']=\MapaSource\SourceSync::CONTRACT_V2;$v2['source_timezone']='Asia/Kolkata';$v2['capabilities']=\MapaSource\SourceSync::capabilitiesFor($v2['contract']);
$v2Fields=\MapaSource\SourceSync::fieldsFor($v2['contract']);
foreach($v2Fields as $dataset=>$fields){$oldRows=$v2['datasets'][$dataset]??[];$v2['datasets'][$dataset]=array_map(fn($r)=>array_replace(array_fill_keys($fields,null),$r),$oldRows);}
$makeCad=function($id,$state)use($v2Fields){return array_replace(array_fill_keys($v2Fields['cad_incidents'],null),['id'=>$id,'incident_number'=>'DEMO incident '.$id,'incident_type'=>'DEMO','priority'=>'unknown','status'=>$state]);};
$v2['datasets']['cad_incidents']=[$makeCad('DEMO-C1','pending'),$makeCad('DEMO-C2','dispatched'),$makeCad('DEMO-C3','completed'),$makeCad('DEMO-C4','cancelled')];
$connectionState['snapshot']=$v2;$writeConnectionState();$dashboard=new App\MapaMobile\SourceDashboardController;
$opsSource=$dashboard->index($connectionReq(),'operations');$opsData=$opsSource->getData(true);
check($opsSource->getStatusCode()===200&&$opsData['counts']['asr_active_incidents']===2,'native Operations source feed excludes completed/cancelled calls');
check($opsData['read_only']&&$opsData['dispatch_reservation']===false&&$opsData['owner']==='asrhealth.in','source call visibility is labelled advisory and source-owned');
check(count($opsData['sections']['source_owned_calls'])===2,'source active calls display without native order duplication');
check($dashboard->index($connectionReq(),'maintenance')->getStatusCode()===200,'native Maintenance consumes shared v2 source generation');
check($dashboard->index($connectionReq(),'analytics')->getData(true)['statistics_unit']!==null,'source statistics explicitly remain separate from MAPA journeys');
check($dashboard->index($connectionReq(),'resources')->getData(true)['counts']['asr_ambulances']===2,'Resources source counts are real snapshot counts');
check($dashboard->index($connectionReq([],['company_id'=>$foreign]),'operations')->getStatusCode()===422,'dashboard cannot select browser-supplied tenant');
check($dashboard->index($connectionReq(),'unknown')->getStatusCode()===422,'arbitrary dashboard refused');
check($dashboard->index($connectionReq([],[],str_repeat('x',40)),'operations')->getStatusCode()===401,'source dashboard rejects unauthenticated token');
check($resourceCounts()===$beforeConnections,'mapping/projection/review changes no native account, duty, GPS, assignment or trip records');
echo "SOURCE_CONNECTION_CASES_COMPLETE: ambulance, driver and hospital native mappings verified.\n";
unlink($connectionDir.'/connections.json');unlink($connectionDir.'/state.json');
config(['mapa_mobile.source_sync_enabled'=>$connectionPrior[0],'mapa_mobile.source_connections_enabled'=>$connectionPrior[1],'mapa_mobile.source_connections_demo_enabled'=>$connectionPrior[2]]);
DB::rollBack();
